    @Test
    public void testCreateNumber_AllZerosCheck() throws NumberFormatException {
        // Test the logic where allZeros is used to prevent returning 0.0 if it's actually non-zero precision
        assertEquals(0.0f, (Float) NumberUtils.createNumber("0.0f"), 0.001);
        assertEquals(0.0, (Double) NumberUtils.createNumber("0.0d"), 0.001);
        assertEquals(new BigDecimal("0.0"), NumberUtils.createNumber("0.0"));
    }








}

